  props: {
    variant: {
      type: String,
      validator (value) {
        return Object.values(MESSAGE_VARIANTS).indexOf(value) !== -1
      }
    },
    messageHash: String,
    text: String,
    type: String,
    isMsgSender: Boolean,
    isGroupCreator: Boolean,
    isAlreadyPinned: Boolean
  },
  data () {
    return {
      isDesktopScreen: true,
      isToDown: false
    }
