ew-non-media .c-non-media-icon[data-v-e7d95b30] {\n  grid-area: preview-icon;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: inherit;\n  width: 2.5rem;\n  height: 2.5rem;\n  font-size: 1.25rem;\n  color: var(--primary_0);\n  background-color: var(--primary_2);\n}\n.c-attachment-preview .c-preview-non-media .c-non-media-file-info[data-v-e7d95b30] {\n  grid-area: preview-info;\n  position: relative;\n  display: block;\n  line-height: 1.2;\n  width: 100%;\n}\n.c-attachment-preview .c-preview-non-media .c-non-media-file-info .c-file-name[data-v-e7d95b30] {\n  position: relative;\n  font-weight: bold;\n  max-width: 13.25rem;\n}\n.c-attachment-preview button.c-attachment-remove-btn[data-v-e7d95b30] {\n  position: absolute;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  top: 0;\n  right: 0;\n  transform: translate(50%, -50%);\n  z-index: 2;\n  width: 1.125rem;\n  height: 1.125rem;\n  border-radius: 1rem;\n  font-weight: 600;\n  font-size: 0.75rem;\n  background-color: var(--text_1);\n  color: var(--general_1);\n}\n.c-invisible-link[data-v-e7d95b30] {\n  position: absolute;\n  top: -10rem;\n  left: -10rem;\n  opacity: 0;\n  pointer-events: none;\n}\n.c-non-media-card-container[data-v-e7d95b30],\n.c-audio-card-container[data-v-e7d95b30],\n.c-image-card-container[data-v-e7d95b30],\n.c-video-card-container[data-v-e7d95b30] {\n  position: relative;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 1rem;\n}\n.c-audio-card-container[data-v-e7d95b30],\n.c-video-card-container[data-v-e7d95b30] {\n  flex-direction: column;\n  flex-wrap: nowrap;\n}\n.c-image-card-container[data-v-e7d95b30] {\n  align-items: flex-end;\n}\n\n/*# sourceMappingURL=ChatAttachmentPreview.vue.map */", map: {"version":3,"sources":["ChatAttachmentPreview.vue","frontend/views/containers/chatroom/file-attachment/ChatAttachmentPreview.vue"],"names":[],"mappings":"AAAA;EACE,YAAY;EACZ,gBAAgB;EAChB,SAAS;EACT,UAAU;EACV,WAAW;EACX,iBAAiB;EACjB,gBAAgB;EAChB,uBAAuB;EACvB,uCAAuC;EACvC,cAAc;EACd,aAAa;EACb,4EAA4E;EAC5E,mBAAmB;EACnB,uCAAuC;EACvC,+BAA+B;EAC/B,gCAAgC;EAChC,+DAA+D;EAC/D,wBAAwB;EACxB,mDAAmD;AACrD;AAEA;EACE,SAAS;EACT,UAAU;AACZ;ACwbA;EACA,kBAAA;EACA,iBAAA;EACA,WAAA;EACA,eAAA;EACA,SAAA;ADrbA;ACubA;EACA,UAAA;EACA,aAAA;EACA,sBAAA;EACA,oBAAA;EACA,aAAA;EACA,mBAAA;ADrbA;ACybA;EACA,kBAAA;EACA,qBAAA;EACA,kCAAA;EACA,0CAAA;EACA,sBAAA;EACA,cAAA;ADtbA;ACwbA;EAEA,mBAAA;EACA,gBAAA;EACA,kBAAA;ADvbA;AC0bA;EACA,kBAAA;EACA,WAAA;EACA,YAAA;EACA,sBAAA;EACA,kCAAA;EACA,aAAA;EACA,+BAAA;EACA,uBAAA;EACA,gDAAA;EACA,mBAAA;EACA,eAAA;EACA,WAAA;ADxbA;AC0bA;EACA,uBAAA;EACA,oBAAA;EACA,mBAAA;EACA,uBAAA;EACA,sBAAA;EACA,aAAA;EACA,cAAA;EACA,kBAAA;EACA,uBAAA;EACA,kCAAA;ADxbA;AC2bA;EACA,uBAAA;EACA,kBAAA;EACA,cAAA;EACA,gBAAA;EACA,WAAA;ADzbA;AC2bA;EACA,kBAAA;EACA,iBAAA;EACA,mBAAA;ADzbA;AC8bA;EAEA,kBAAA;EACA,oBAAA;EACA,mBAAA;EACA,uBAAA;EACA,MAAA;EACA,QAAA;EACA,+BAAA;EACA,UAAA;EACA,eAAA;EACA,gBAAA;EACA,mBAAA;EACA,gBAAA;EACA,kBAAA;EACA,+BAAA;EACA,uBAAA;AD7bA;ACicA;EACA,kBAAA;EACA,WAAA;EACA,YAAA;EACA,UAAA;EACA,oBAAA;AD9bA;ACicA;;;;EAIA,kBAAA;EACA,aAAA;EACA,eAAA;EACA,SAAA;AD9bA;ACicA;;EAEA,sBAAA;EACA,iBAAA;AD9bA;ACicA;EACA,qBAAA;AD9bA;;AAEA,oDAAoD","file":"ChatAttachmentPreview.vue","sourcesContent":[".c-attachment-preview button.c-attachment-remove-btn {\n  border: none;\n  border-radius: 0;\n  margin: 0;\n  padding: 0;\n  width: auto;\n  overflow: visible;\n  min-height: auto;\n  background: transparent;\n  /* inherit font & color from ancestor */\n  color: inherit;\n  font: inherit;\n  /* Normalize `line-height`. Cannot be changed from `normal` in Firefox 4+. */\n  line-height: normal;\n  /* Corrects font smoothing for webkit */\n  -webkit-font-smoothing: inherit;\n  -moz-osx-font-smoothing: inherit;\n  /* Corrects inability to style clickable `input` types in iOS */\n  -webkit-appearance: none;\n  /* Remove excess padding and border in Firefox 4+ */\n}\n\n.c-attachment-preview button.c-attachment-remove-btn::-moz-focus-inner {\n  border: 0;\n  padding: 0;\n}\n\n.c-attachment-container {\n  position: relative;\n  padding: 0 0.5rem;\n  width: 100%;\n  max-width: 100%;\n  gap: 1rem;\n}\n.c-attachment-container.is-for-download {\n  padding: 0;\n  display: flex;\n  flex-direction: column;\n  align-items: stretch;\n  row-gap: 1rem;\n  margin-top: 0.75rem;\n}\n\n.c-attachment-preview {\n  position: relative;\n  display: inline-block;\n  border: 1px solid var(--general_0);\n  box-shadow: 0 0 4px rgba(29, 28, 29, 0.13);\n  border-radius: 0.25rem;\n  flex-shrink: 0;\n}\n.c-attachment-preview.is-audio, .c-attachment-preview.is-non-media {\n  max-width: 17.25rem;\n  min-width: 14rem;\n  min-height: 3.5rem;\n}\n.c-attachment-preview .c-preview-non-media {\n  position: relative;\n  width: 100%;\n  height: 100%;\n  border-radius: inherit;\n  background-color: var(--general_2);\n  display: grid;\n  grid-template-columns: auto 1fr;\n  grid-template-rows: 1fr;\n  grid-template-areas: \"preview-icon preview-info\";\n  align-items: center;\n  padding: 0.5rem;\n  gap: 0.5rem;\n}\n.c-attachment-preview .c-preview-non-media .c-non-media-icon {\n  grid-area: preview-icon;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: inherit;\n  width: 2.5rem;\n  height: 2.5rem;\n  font-size: 1.25rem;\n  color: var(--primary_0);\n  background-color: var(--primary_2);\n}\n.c-attachment-preview .c-preview-non-media .c-non-media-file-info {\n  grid-area: preview-info;\n  position: relative;\n  display: block;\n  line-height: 1.2;\n  width: 100%;\n}\n.c-attachment-preview .c-preview-non-media .c-non-media-file-info .c-file-name {\n  position: relative;\n  font-weight: bold;\n  max-width: 13.25rem;\n}\n.c-attachment-preview button.c-attachment-remove-btn {\n  position: absolute;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  top: 0;\n  right: 0;\n  transform: translate(50%, -50%);\n  z-index: 2;\n  width: 1.125rem;\n  height: 1.125rem;\n  border-radius: 1rem;\n  font-weight: 600;\n  font-size: 0.75rem;\n  background-color: var(--text_1);\n  color: var(--general_1);\n}\n\n.c-invisible-link {\n  position: absolute;\n  top: -10rem;\n  left: -10rem;\n  opacity: 0;\n  pointer-events: none;\n}\n\n.c-non-media-card-container,\n.c-audio-card-container,\n.c-image-card-container,\n.c-video-card-container {\n  position: relative;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 1rem;\n}\n\n.c-audio-card-container,\n.c-video-card-container {\n  flex-direction: column;\n  flex-wrap: nowrap;\n}\n\n.c-image-card-container {\n  align-items: flex-end;\n}\n\n/*# sourceMappingURL=ChatAttachmentPreview.vue.map */","<template lang='pug'>\n.c-attachment-container(ref='container' :class='{ \"is-for-download\": isForDownload }')\n\n  // Displaying attachments as part of message\n  template(v-if='isForDownload')\n    .c-non-media-card-container(v-if='hasAttachmentType(config.CHATROOM_ATTACHMENT_TYPES.NON_MEDIA)')\n      attachment-download-item(\n        v-for='(entry, entryIndex) in sortedAttachments[config.CHATROOM_ATTACHMENT_TYPES.NON_MEDIA]'\n        :key='getAttachmentId(entry)'\n        :attachment='entry'\n        :variant='variant'\n        :canDelete='canDelete'\n        @download='downloadAttachment(entry)'\n        @delete='deleteAttachment({ index: entryIndex, type: config.CHATROOM_ATTACHMENT_TYPES.NON_MEDIA })'\n      )\n\n    .c-image-card-container(v-if='hasAttachmentType(config.CHATROOM_ATTACHMENT_TYPES.IMAGE)')\n      attachment-download-item(\n        v-for='(entry, entryIndex) in sortedAttachments[config.CHATROOM_ATTACHMENT_TYPES.IMAGE]'\n        :key='getAttachmentId(entry)'\n        :attachment='entry'\n        :variant='variant'\n        :canDelete='canDelete'\n        :mediaObjectURL='mediaObjectURLList.image[entryIndex]'\n        @download='downloadAttachment(entry, mediaObjectURLList.image[entryIndex])'\n        @delete='deleteAttachment({ index: entryIndex, type: config.CHATROOM_ATTACHMENT_TYPES.IMAGE })'\n      )\n\n    .c-audio-card-container(v-if='hasAttachmentType(config.CHATROOM_ATTACHMENT_TYPES.AUDIO)')\n      attachment-download-item(\n        v-for='(entry, entryIndex) in sortedAttachments[config.CHATROOM_ATTACHMENT_TYPES.AUDIO]'\n        :key='getAttachmentId(entry)'\n        :attachment='entry'\n        :variant='variant'\n        :canDelete='canDelete'\n        :mediaObjectURL='mediaObjectURLList.audio[entryIndex]'\n        @download='downloadAttachment(entry)'\n        @delete='deleteAttachment({ index: entryIndex, type: config.CHATROOM_ATTACHMENT_TYPES.AUDIO })'\n      )\n\n    .c-video-card-container(v-if='hasAttachmentType(config.CHATROOM_ATTACHMENT_TYPES.VIDEO)')\n      attachment-download-item(\n        v-for='(entry, entryIndex) in sortedAttachments[config.CHATROOM_ATTACHMENT_TYPES.VIDEO]'\n        :key='getAttachmentId(entry)'\n        :attachment='entry'\n        :variant='variant'\n        :canDelete='canDelete'\n        :mediaObjectURL='mediaObjectURLList.video[entryIndex]'\n        @download='downloadAttachment(entry, mediaObjectURLList.video[entryIndex])'\n        @delete='deleteAttachment({ index: entryIndex, type: config.CHATROOM_ATTACHMENT_TYPES.VIDEO })'\n      )\n\n  // Displaying attachments as part of <send-area />\n  template(v-else)\n    send-area-attachments-gallery\n      template(v-for='(entry, entryIndex) in attachmentList')\n        .c-attachment-preview(\n          v-if='[config.CHATROOM_ATTACHMENT_TYPES.NON_MEDIA, config.CHATROOM_ATTACHMENT_TYPES.AUDIO].includes(fileType(entry))'\n          :key='entry.url'\n          :class='\"is-\" + fileType(entry)'\n        )\n          .c-preview-non-media(@click.stop='')\n            .c-non-media-icon\n              i.icon-headphones(v-if='fileType(entry) === config.CHATROOM_ATTACHMENT_TYPES.AUDIO')\n              i.icon-file(v-else)\n\n            .c-non-media-file-info\n              .c-file-name.has-ellipsis {{ entry.name }}\n              .c-file-ext {{ fileExt(entry) }}\n\n          button.c-attachment-remove-btn(\n            type='button'\n            :aria-label='L(\"Remove attachment\")'\n            @click.stop='$emit(\"remove\", entry.url)'\n          )\n            i.icon-times\n\n        media-preview-in-text-area(\n          v-else\n          :key='entry.url'\n          :attachment='entry'\n          @remove='$emit(\"remove\", entry.url)'\n          @click='onMediaPreviewCardClick(fileType(entry), entry.url)'\n        )\n\n  a.c-invisible-link(ref='downloadHelper')\n</template>\n\n<script>\nimport sbp from '@sbp/sbp'\nimport AttachmentDownloadItem from './AttachmentDownloadItem.vue'\nimport MediaPreviewInTextArea from './MediaPreviewInTextArea.vue'\nimport SendAreaAttachmentsGallery from './SendAreaAttachmentsGallery.vue'\nimport Tooltip from '../../../../../frontend/views/components/Tooltip.vue'\nimport { MESSAGE_VARIANTS, CHATROOM_ATTACHMENT_TYPES } from '../../../../../frontend/model/contracts/shared/constants.js'\nimport { getFileExtension, getFileType } from '../../../../../frontend/views/utils/filters.js'\nimport { Secret } from '@chelonia/lib/Secret'\nimport { OPEN_MODAL, DELETE_ATTACHMENT } from '../../../../../frontend/utils/events.js'\nimport { uniq } from 'turtledash'\n\nexport default {\n  name: 'ChatAttachmentPreview',\n  components: {\n    Tooltip,\n    AttachmentDownloadItem,\n    MediaPreviewInTextArea,\n    SendAreaAttachmentsGallery\n  },\n  props: {\n    attachmentList: {\n      type: Array,\n      required: true\n    },\n    variant: {\n      type: String,\n      validator (value) {\n        return Object.values(MESSAGE_VARIANTS).indexOf(value) !== -1\n      }\n    },\n    isGroupCreator: Boolean,\n    isForDownload: Boolean,\n    isMsgSender: Boolean,\n    ownerID: String,\n    createdAt: [Date, String]\n  },\n  data () {\n    return {\n      mediaObjectURLList: {\n        [CHATROOM_ATTACHMENT_TYPES.IMAGE]: [],\n        [CHATROOM_ATTACHMENT_TYPES.VIDEO]: [],\n        [CHATROOM_ATTACHMENT_TYPES.AUDIO]: []\n      },\n      settledImgURLList: [],\n      config: {\n        CHATROOM_ATTACHMENT_TYPES: CHATROOM_ATTACHMENT_TYPES\n      }\n    }\n  },\n  computed: {\n    sortedAttachments () {\n      const collections = {\n        [CHATROOM_ATTACHMENT_TYPES.NON_MEDIA]: [],\n        [CHATROOM_ATTACHMENT_TYPES.IMAGE]: [],\n        [CHATROOM_ATTACHMENT_TYPES.VIDEO]: [],\n        [CHATROOM_ATTACHMENT_TYPES.AUDIO]: []\n      }\n\n      for (const entry of this.attachmentList) {\n        const fType = getFileType(entry.mimeType)\n        collections[fType].push(entry)\n      }\n\n      return collections\n    },\n    hasImgAttachments () {\n      return this.sortedAttachments[CHATROOM_ATTACHMENT_TYPES.IMAGE].length > 0\n    },\n    hasVideoAttachments () {\n      return this.sortedAttachments[CHATROOM_ATTACHMENT_TYPES.VIDEO].length > 0\n    },\n    hasAudioAttachments () {\n      return this.sortedAttachments[CHATROOM_ATTACHMENT_TYPES.AUDIO].length > 0\n    },\n    hasMediaAttachments () {\n      return this.hasImgAttachments || this.hasVideoAttachments || this.hasAudioAttachments\n    },\n    isPending () {\n      return this.variant === MESSAGE_VARIANTS.PENDING\n    },\n    isFailed () {\n      return this.variant === MESSAGE_VARIANTS.FAILED\n    },\n    canDelete () {\n      return this.isMsgSender || this.isGroupCreator\n    }\n  },\n  mounted () {\n    if (this.hasMediaAttachments) {\n      this.initMediaObjectURLLists()\n      sbp('okTurtles.events/on', DELETE_ATTACHMENT, this.deleteAttachment)\n    }\n  },\n  beforeDestroy () {\n    if (this.hasMediaAttachments) {\n      sbp('okTurtles.events/off', DELETE_ATTACHMENT, this.deleteAttachment)\n\n      if (this.isForDownload) {\n        // make sure to revoke all media object URLs when the component is destroyed\n        this.revokeAllMediaObjectURLs()\n      }\n    }\n  },\n  methods: {\n    initMediaObjectURLLists () {\n      const types = [\n        CHATROOM_ATTACHMENT_TYPES.IMAGE,\n        CHATROOM_ATTACHMENT_TYPES.VIDEO,\n        CHATROOM_ATTACHMENT_TYPES.AUDIO\n      ]\n\n      for (const mediaType of types) {\n        if (this.sortedAttachments[mediaType].length === 0) { continue }\n\n        const promiseToRetrieveURLs = this.sortedAttachments[mediaType]\n          .map(async attachment => {\n            try {\n              if (mediaType === CHATROOM_ATTACHMENT_TYPES.IMAGE) {\n                return this.getAttachmentObjectURL(attachment)\n              } else {\n                if (attachment.url) {\n                  return attachment.url\n                } else if (attachment.downloadData?.manifestCid) {\n                  const cachedArrayBuffer = await sbp('gi.db/filesCache/temporary/load', attachment.downloadData.manifestCid)\n                  return cachedArrayBuffer ? URL.createObjectURL(new Blob([cachedArrayBuffer])) : ''\n                }\n                return ''\n              }\n            } catch (err) {\n              console.error('[ChatAttachmentPreview/initMediaObjectURLList] Error:', err)\n              return ''\n            }\n          })\n\n        Promise.all(promiseToRetrieveURLs).then(urls => {\n          this.mediaObjectURLList[mediaType] = urls\n        })\n      }\n    },\n    hasAttachmentType (type) {\n      return this.sortedAttachments[type].length > 0\n    },\n    fileExt ({ name }) {\n      return getFileExtension(name, true)\n    },\n    fileType ({ mimeType }) {\n      return getFileType(mimeType)\n    },\n    deleteAttachment ({ index, url, type }) {\n      // If index is not explicitly provided, look up the index by the URL.\n      if (index === undefined &&\n        [CHATROOM_ATTACHMENT_TYPES.IMAGE, CHATROOM_ATTACHMENT_TYPES.VIDEO, CHATROOM_ATTACHMENT_TYPES.AUDIO].includes(type) &&\n        url) {\n        index = this.mediaObjectURLList[type].indexOf(url)\n      }\n\n      if (index >= 0) {\n        const attachment = this.sortedAttachments[type][index]\n        if (attachment.downloadData) {\n          this.$emit('delete-attachment', attachment.downloadData.manifestCid)\n        }\n      }\n    },\n    async getAttachmentObjectURL (attachment) {\n      if (attachment.url) {\n        return attachment.url\n      } else if (attachment.downloadData) {\n        const manifestCid = attachment.downloadData.manifestCid\n        const cachedArrayBuffer = await sbp('gi.db/filesCache/temporary/load', manifestCid)\n\n        if (cachedArrayBuffer) {\n          return URL.createObjectURL(new Blob([cachedArrayBuffer]))\n        } else {\n          const blob = await sbp('chelonia/fileDownload', new Secret(attachment.downloadData))\n          const arrayBuffer = await blob.arrayBuffer()\n          sbp('gi.db/filesCache/temporary/save', manifestCid, arrayBuffer)\n          return URL.createObjectURL(blob)\n        }\n      }\n    },\n    revokeAllMediaObjectURLs () {\n      Object.values(this.mediaObjectURLList).forEach(urlList => {\n        urlList.forEach(url => URL.revokeObjectURL(url))\n      })\n    },\n    async loadMediaObjectURL (attachment, mediaType) {\n      const downloadData = attachment.downloadData\n\n      if (downloadData?.manifestCid) {\n        const manifestCid = downloadData.manifestCid\n        const cachedArrayBuffer = await sbp('gi.db/filesCache/temporary/load', manifestCid)\n        const blobToUse = cachedArrayBuffer\n          ? new Blob([cachedArrayBuffer], { type: attachment.mimeType })\n          : (await sbp('chelonia/fileDownload', new Secret(downloadData)))\n\n        const index = this.sortedAttachments[mediaType]\n          .findIndex(a => a.downloadData?.manifestCid === downloadData.manifestCid)\n\n        if (index >= 0) {\n          this.mediaObjectURLList[mediaType] = this.mediaObjectURLList[mediaType].map((url, i) => {\n            if (i !== index) { return url }\n\n            if (url) {\n              URL.revokeObjectURL(url)\n            }\n            return URL.createObjectURL(blobToUse)\n          })\n        }\n\n        if (!cachedArrayBuffer) {\n          const arrayBuffer = await blobToUse.arrayBuffer()\n          sbp('gi.db/filesCache/temporary/save', manifestCid, arrayBuffer)\n        }\n      }\n    },\n    async downloadAttachment (attachment, objectURL = null) {\n      if (!attachment.downloadData) { return }\n\n      // reference: https://blog.logrocket.com/programmatically-downloading-files-browser/\n      try {\n        const url = objectURL || (await this.getAttachmentObjectURL(attachment))\n\n        const aTag = this.$refs.downloadHelper\n        aTag.setAttribute('href', url)\n        aTag.setAttribute('download', attachment.name)\n\n        aTag.addEventListener('click', function (event) {\n          // NOTE: should call stopPropagation here to keep showing the PinnedMessages dialog\n          //       when user trys to download attachment inside the dialog\n          event.stopPropagation()\n        })\n\n        aTag.click()\n      } catch (err) {\n        console.error('error caught while downloading a file: ', err)\n      }\n    },\n    getStretchedDimension ({ width, height }) {\n      // NOTE: 320px = 20rem of max-height (.loading-box)\n      const maxHeight = 320\n      // NOTE: 16px = 2 * 0.5rem of padding (.c-preview-img)\n      //       2px = 2 * 1px of border width (.c-attachment-preview)\n      const maxWidth = this.$refs.container.clientWidth - 16 - 2\n      const zoomRatio = Math.min(maxWidth / width, maxHeight / height, 1)\n      const widthInPixel = zoomRatio * width\n      const heightInPixel = zoomRatio * height\n\n      return {\n        width: `${widthInPixel}px`,\n        height: `${heightInPixel}px`\n      }\n    },\n    onMediaPreviewCardClick (type, url) {\n      const func = ({\n        image: this.openImageViewer,\n        video: this.openVideoViewer\n      })[type]\n\n      func && func(url)\n    },\n    openVideoViewer (objectURL, additionalData = null) {\n      if (objectURL) {\n        this.openMediaViewer(CHATROOM_ATTACHMENT_TYPES.VIDEO, objectURL, additionalData)\n      }\n    },\n    openImageViewer (objectU