    'chatMainConfig.isPhone' () {
      if (this.shouldCheckToTruncate) {
        this.determineToEnableTruncationToggle()
      }
    },
    updatedDate (newVal) {
      if (newVal && this.shouldCheckToTruncate) {
        // When the messge is edited, check again if truncate-toggle is needed.
        this.$nextTick(() => {
          this.determineToEnableTruncationToggle()
        })
      }
    }
  },
