      Vue.set(this.form.options, this.optionCount, {
        id: newOptionId,
        value: ''
      })

      this.$nextTick(() => {
        const newInputEl = this.$refs.optList?.querySelector('.c-option-item:last-of-type > .input')

        newInputEl && newInputEl.focus()
      })
    },
